-- Live definition exported from the database (view league_standings).
-- Do not edit here: change it with a migration; the next export will reflect it.

create or replace view public.league_standings as
 SELECT league_id,
    league_code,
    league_name,
    tier,
    season_id,
    season_label,
    team_id,
    "position",
    pyramid_position,
    teams,
    is_final,
    curtailed,
    ranked_on,
    played,
    won,
    drawn,
    lost,
    goals_for,
    goals_against,
    clean_sheets,
    failed_to_score,
    points_won,
    deduction,
    points,
    ppg,
    home_played,
    home_points,
    home_goals_for,
    home_goals_against,
    away_played,
    away_points,
    away_goals_for,
    away_goals_against,
    home_won,
    home_drawn,
    home_lost,
    home_clean_sheets,
    away_won,
    away_drawn,
    away_lost,
    away_clean_sheets,
    season_start_year,
    split_group,
    split_adjustment
   FROM league_standings_cache;
